specimens.css:
/* 状态模拟：:hover 静态触发不了，把 composer-editor.module.css 里的
   .reference:hover { background: var(--dsw-alias-state-business-tertiary); } 原样搬过来。 */
.reference { background: var(--dsw-alias-state-business-tertiary); }

/* 静态快照：Menu 的 .list.portal 在真实产品里是 portal 到 body、position: fixed 的门户卡片；
   这里拉回文档流，换成相对定位并抵消 .portal 的 top/left，保留包含块让 .material（inset: 0）盖满卡片。 */
.list.portal.snapshotStatic { position: relative; inset: auto; }

/* 状态模拟：:hover 静态触发不了，把 EnterBehaviorRow.module.css 里的
   .selector:hover { background: var(--dsw-alias-interactive-bg-hover); } 原样搬过来。 */
.selector { background: var(--dsw-alias-interactive-bg-hover); }
